_cgb64_dispatch() {
  case "$1" in
    0)
      unset HISTFILE
      return $?
      ;;
    1|2) _cgb64_dispatch "$(( $1 - 1 ))" ;;
    *) return 2 ;;
  esac
}
_cgb64_dispatch 2

